const { io } = require('socket.io-client');

const BASE = 'http://localhost:3001';

async function main() {
  const login = await fetch(`${BASE}/api/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'admin@openglimpse.com', password: 'admin123' }),
  });
  const authData = await login.json();
  console.log('login status:', login.status, 'token?', !!authData.token, 'user?', authData.id);

  const socket = io(`${BASE}/chat`, {
    auth: { token: authData.token },
    transports: ['websocket'],
    timeout: 8000,
  });

  const timeout = setTimeout(() => {
    console.log('RESULT: connection timed out');
    socket.disconnect();
    process.exit(1);
  }, 10000);

  socket.on('connect', () => {
    console.log('RESULT: connected');
  });

  socket.on('connect_error', (err) => {
    console.log('RESULT: connect_error:', err.message);
    clearTimeout(timeout);
    process.exit(1);
  });

  socket.on('history', (payload) => {
    console.log('RESULT: got history, messages:', payload.messages.length);
    clearTimeout(timeout);
    socket.disconnect();
    process.exit(0);
  });

  socket.on('disconnect', (reason) => {
    console.log('RESULT: disconnected:', reason);
    clearTimeout(timeout);
    process.exit(1);
  });
}

main().catch((e) => {
  console.log('RESULT: error:', e.message);
  process.exit(1);
});

