const { io } = require('socket.io-client');

const BASE = 'http://localhost:3001';

async function main() {
  const login = await fetch(`${BASE}/api/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'admin@openglimpse.com', password: 'admin123' }),
  });
  const authData = await login.json();

  const socket = io(`${BASE}/chat`, {
    auth: { token: authData.token },
    transports: ['websocket'],
    timeout: 8000,
  });

  const timeout = setTimeout(() => { console.log('RESULT: timed out'); process.exit(1); }, 10000);

  socket.on('connect', () => {
    socket.emit('chat:join', '00000000-0000-0000-0000-000000000000');
    socket.emit('message', { text: 'socket smoke test ' + Date.now() });
  });

  socket.on('message', (payload) => {
    console.log('RESULT: received message back:', payload.message.text.slice(0, 40));
    clearTimeout(timeout);
    process.exit(0);
  });

  socket.on('connect_error', (err) => {
    console.log('RESULT: connect_error:', err.message);
    process.exit(1);
  });

  socket.on('error', (payload) => {
    console.log('RESULT: socket error event:', JSON.stringify(payload));
